CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'customer');
CREATE TABLE IF NOT EXISTS products(id SERIAL PRIMARY KEY,name TEXT NOT NULL,category TEXT NOT NULL,price_cents INTEGER NOT NULL CHECK(price_cents>=0),inventory INTEGER NOT NULL CHECK(inventory>=0),image_url TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS orders(id SERIAL PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),subtotal_cents INTEGER NOT NULL,discount_cents INTEGER NOT NULL,tax_cents INTEGER NOT NULL,total_cents INTEGER NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS order_items(order_id INTEGER REFERENCES orders(id),product_id INTEGER REFERENCES products(id),quantity INTEGER NOT NULL CHECK(quantity>0),unit_price_cents INTEGER NOT NULL,PRIMARY KEY(order_id,product_id));
CREATE TABLE IF NOT EXISTS idempotency_keys(user_id INTEGER REFERENCES users(id),key TEXT NOT NULL,order_id INTEGER REFERENCES orders(id),PRIMARY KEY(user_id,key));
CREATE TABLE IF NOT EXISTS test_runs(id SERIAL PRIMARY KEY,suite TEXT NOT NULL,passed INTEGER NOT NULL,failed INTEGER NOT NULL,duration_ms INTEGER NOT NULL,details JSONB NOT NULL DEFAULT '[]',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS defects(id SERIAL PRIMARY KEY,title TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',description TEXT NOT NULL);
INSERT INTO products(name,category,price_cents,inventory,image_url) SELECT * FROM (VALUES ('Honeycrisp Apples','Produce',299,40,'https://images.unsplash.com/photo-1560806887-1e4cd0b6cbd6?w=600'),('Fresh Avocados','Produce',149,30,'https://images.unsplash.com/photo-1523049673857-eb18f1d7b578?w=600'),('Whole Grain Bread','Bakery',349,20,'https://images.unsplash.com/photo-1509440159596-0249088772ff?w=600'),('Organic Milk','Dairy',499,25,'https://images.unsplash.com/photo-1550583724-b2692b85b150?w=600'),('Brown Eggs','Dairy',399,35,'https://images.unsplash.com/photo-1506976785307-8732e854ad03?w=600'),('Ground Coffee','Pantry',1099,18,'https://images.unsplash.com/photo-1447933601403-0c6688de566e?w=600')) AS v(name,category,price_cents,inventory,image_url) WHERE NOT EXISTS(SELECT 1 FROM products);
